-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Heilig"
L["rm.era.paladin.holy.Description"] = "Heilung in einer Gruppe mit dem Heilig-Baum, ab Stufe 10. Wirkt auf Ihr freundliches Ziel und wählt die Heilung nach fehlender Gesundheit: Reinigung des Glaubens oder Läutern, Heiliger Schock in Bewegung, Heiliges Licht im höchsten Rang unter 40 %, Heiliges Licht Rang 6 unter 65 %, Lichtblitz im höchsten Rang unter 85 %, Lichtblitz Rang 4 unter 95 %. Mit einem Gegner in Nahkampfreichweite: Siegel der Weisheit und, außerhalb von Schlachtzügen, Richturteil. Erinnerungen: Aura der Konzentration oder der Hingabe, Segen der Weisheit, Göttliche Gunst und Handauflegung für ein Ziel mit sehr wenig Gesundheit. Wen Sie heilen, bleibt Ihnen überlassen; Heilig-Paladine im Solospiel erhalten die integrierte Vergeltungsrotation."
L["rm.era.paladin.protection.Name"] = "Schutz"
L["rm.era.paladin.protection.Description"] = "Tanken von Stufe 1 bis 60, gewählt durch Zorn der Gerechtigkeit oder den Schutzbaum. Siegel der Rechtschaffenheit (Siegel der Weisheit, wenn das Mana unter 40 % fällt), Heiliger Schild und Richturteil zum Ziehen, Heiliger Schild aufrechterhalten, Weihe und Heiliger Zorn (Untote und Dämonen), wenn zwei oder mehr Gegner gegen Sie kämpfen, sonst einmal Richturteil des Kreuzfahrers, dann Richturteil und Weihe bei überschüssigem Mana, Exorzismus gegen Untote und Dämonen. Erinnerungen: Zorn der Gerechtigkeit, Aura der Hingabe, Refugium, Könige oder Macht, Handauflegung kurz vor dem Tod. Spotten, Dauereinsatz von Segen der Könige und Zauberränge bleiben Ihnen überlassen."
L["rm.era.paladin.protection.icyveins.Name"] = "Schutz, Siegel der Weisheit (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "Schlachtzugstanken nach Icy Veins mit der Weisheitsrotation von Wowhead, eine Alternative zur empfohlenen integrierten Schutzrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hält Siegel der Weisheit aufrecht und richtet es, wann immer dem Ziel Richturteil der Weisheit fehlt, sonst richtet sie nur zum Ziehen; Heiliger Schild, Weihe bei jedem Abklingzeit-Ende, Heiliger Zorn gegen Gruppen von Untoten und Dämonen, Exorzismus und Großer Segen der Könige als Bedrohungsfüller im Schlachtzug. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.era.paladin.retribution.Name"] = "Vergeltung"
L["rm.era.paladin.retribution.Description"] = "Vergeltung im Nahkampf von Stufe 1 bis 60 und der Standard für jeden Paladin, zu dem keine andere integrierte Rotation passt. Gegen Elitegegner und bei langen Kämpfen außerhalb von Schlachtzügen setzt sie Siegel des Kreuzfahrers und richtet es einmal; sonst hält sie ein Siegel aufrecht (Befehl mit einer Waffe von 3,5 Sekunden oder langsamer, sonst Rechtschaffenheit), Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Hammer des Zorns, Richturteil bei Abklingzeit-Ende, Weihe, solange Rache aktiv ist, oder gegen zwei oder mehr nahe Gegner. Erinnerungen: Aura der Heiligkeit, der Vergeltung oder der Hingabe, Segen der Weisheit solo oder Macht in einer Gruppe, eine Heilung zwischen den Kämpfen, Gottesschild, Göttlicher Schutz oder Handauflegung, wenn Sie kurz vor dem Tod stehen. Siegel-Twisting ist eine eigene integrierte Rotation; Zielwahl und Positionierung bleiben Ihnen überlassen."
L["rm.era.paladin.retribution.twist.Name"] = "Vergeltung, Siegel-Twisting"
L["rm.era.paladin.retribution.twist.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie Siegel twisten. Für einen Vergeltungspaladin mit Siegel des Befehls: hält Siegel der Rechtschaffenheit aufrecht, wechselt in den letzten 0,4 Sekunden vor einem Schlag zu Siegel des Befehls Rang 1 und wieder zurück, Richturteil, sobald es bereit ist, Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Hammer des Zorns, Weihe mit Rache. Benötigt viel Mana und gutes Timing. Dieselben Erinnerungen wie die integrierte Vergeltungsrotation."
L["rm.forever.paladin.holy.Name"] = "Heilig"
L["rm.forever.paladin.holy.Description"] = "Gruppenheilung, sobald Heilig Ihr Haupttalentbaum mit 21 Punkten ist (die Stufe von Heiliger Schock), solange Zorn der Gerechtigkeit aus ist (ein Shockadin in einer Gruppe landet ebenfalls hier). Heilt Ihr aktuelles freundliches Ziel: Heiliger Schock auf ein Ziel mit Ihrer Lichtwacht, Lichtwacht im Kampf, Reinigung des Glaubens oder Läutern, Heiliger Schock in Bewegung, Heiliges Licht mit Lichtinfusion, Lichtblitz als Hauptheilung. Gegen einen Gegner: Richturteil des Lichts, wenn Siegel des Lichts aktiv ist, Heiliger Schock, Lichtwacht, Heiliger Stoß, Exorzismus. Erinnerungen: Siegel des Lichts, wenn Sie kein Siegel haben, Göttliche Gunst im Kampf auf ein freundliches Ziel, Ihre Aura und Ihr Segen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht; Heilige Schocks im Notfall, große Heilige Lichter und Handauflegung bleiben Ihnen überlassen."
L["rm.forever.paladin.holy.wowhead.Name"] = "Heilig, Heiliger Schock bei Abklingzeit-Ende (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "Heilstil nach Wowhead, eine Alternative zur empfohlenen integrierten Heilig-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Heiliger Schock als Routineheilung bei Abklingzeit-Ende, Bannungen, Lichtblitz (die Gesundheit ist unter Forever verborgen, daher bleibt Heiliges Licht bei großen Defiziten Ihnen überlassen). Gegen einen Gegner hält sie Ihr Richturteil des Lichts aufrecht, indem sie zu Siegel des Lichts wechselt, richtet und zu Siegel der Rechtschaffenheit zurückwechselt, dann Heiliger Stoß, Exorzismus gegen Untote und Dämonen, Heiliger Schock und Weihe. Dieselben Erinnerungen wie die integrierte Heilig-Rotation."
L["rm.forever.paladin.protection.Name"] = "Schutz (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Tanken, sobald Schutz Ihr Haupttalentbaum ist oder Sie Zorn der Gerechtigkeit aktivieren. Wenn das Ziel gegen jemand anderen kämpft: Richturteil mit Siegel des Furors (der Spott), Schnelles Richturteil, um es zurückzusetzen. Zwei oder mehr Gegner im Kampf: Weihe, Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Heiliger Stoß. Ein Gegner: Exorzismus gegen Untote und Dämonen, Heiliger Stoß, Weihe. Erinnerungen: Zorn der Gerechtigkeit, Siegel des Furors, Richturteil bei Abklingzeit-Ende, Heiliger Schild beim Tanken, Ihre Aura und Ihr Segen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Bollwerk des Templers und Handauflegung. Pullen, Positionierung und anderes Spotten bleiben Ihnen überlassen."
L["rm.forever.paladin.protection.icyveins.Name"] = "Schutz, Weihe zuerst (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "Tankstil nach Icy Veins, eine Alternative zur empfohlenen integrierten Schutzrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Weihe zuerst, wann immer Sie es sich leisten können, auch gegen einen einzelnen Gegner; Richturteil wird für Spott aufgespart (keine Erinnerung bei Abklingzeit-Ende), mit Schnellem Richturteil zum Zurücksetzen; dann Heiliger Stoß und Exorzismus gegen Untote und Dämonen. Ansonsten dieselben Tank-Erinnerungen."
L["rm.forever.paladin.retribution.Name"] = "Vergeltung"
L["rm.forever.paladin.retribution.Description"] = "Vergeltung und jeder Nahkampf-Paladin von Stufe 1 bis 60 und der Forever-Paladin-Standard. Hält ein Schadenssiegel aufrecht, das nur erneuert wird, wenn es ausläuft: Siegel des Kreuzfahrers einmal gegen ein Elite-Ziel gerichtet, dann Siegel des Befehls mit einer langsamen Waffe (3,0 s), sonst Siegel der Rechtschaffenheit. Dann Heiliger Stoß bei Abklingzeit-Ende, Heiliger Schock und Lichtwacht für einen Shockadin, Exorzismus gegen Untote und Dämonen, Weihe gegen drei oder mehr Gegner, Hammer des Zorns, wenn er gewirkt werden kann, und Nahkampf. Richturteil unterliegt nicht der globalen Abklingzeit, daher ist es eine Erinnerung, wann immer ein Siegel aktiv ist. Weitere Erinnerungen: Ihre Aura und Ihr Segen (Aura der Vergeltung und Könige, sobald erlernt; Ihre eigenen bleiben erhalten). Optionaler, standardmäßig deaktivierter Schritt: Hammer der Gerechtigkeit vor einem Richturteil mit Siegel des Befehls. Mana, Gesundheit und die Schlagzeit sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Manasparen, Selbstheilung, Handauflegung und den Siegelwechsel mit Wendung des Lichts. Erstellt aus Beta-Leitfäden für Stufe 30."
L["rm.mop.paladin.holy.Name"] = "Empfohlen"
L["rm.mop.paladin.holy.Description"] = "Für Heilig ab Stufe 10 in der Spezialisierung Heilig. Mit einem Verbündeten im Ziel heilt sie: bei 3 Heiliger Kraft (oder Göttlicher Bestimmung) Licht der Morgendämmerung, wenn drei Personen in Ihrer Nähe verletzt sind, sonst Ewige Flamme auf ein Ziel ohne sie, sonst Wort der Herrlichkeit; Heiliger Schock bei Abklingzeit-Ende; Lichtenergie in Heiliges Strahlen oder Göttliches Licht, drei Stapel Selbstloser Heiler in Heiliges Strahlen oder Lichtblitz; Lichtblitz unter 35 %; Heiliges Strahlen für eine verletzte Gruppe; Göttliches Licht, dann Heiliges Licht zum Auffüllen. Mit einem Gegner im Ziel verursacht sie Schaden: Heiliger Schock, Richturteil, Kreuzfahrerstoß, Heiliges Prisma, Richtspruch, Hammer des Zorns, Denunzierung. Erinnerungen: Siegel der Einsicht, wenn ein anderes Siegel (außer Rechtschaffenheit) oder keines aktiv ist, Segen, Zurechtweisung, Flamme des Glaubens und Geheiligter Schild auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Göttliche Bitte unter 60 % Mana, Hammer des Lichts und Ihre Heil-Abklingzeiten, wenn drei Personen unter 70 % sind, Handauflegung auf ein sterbendes Ziel. Wen Sie heilen, Bannungen und Mouseover-Heilung bleiben Ihnen überlassen."
L["rm.mop.paladin.protection.Name"] = "Empfohlen"
L["rm.mop.paladin.protection.Description"] = "Empfohlen für Schutz ab Stufe 10 in der Spezialisierung Schutz. Zieht mit Schild des Rächers, dann Schild des Rächers bei einem Proc von Oberster Kreuzfahrer, Schild des Rächers, Hammer des Zorns, Kreuzfahrerstoß, Richturteil, Ihr Talent der Stufe 90, Weihe, Heiliger Zorn und Geheiligter Schild. Drei oder mehr Gegner gegen Sie wechseln zu Schild des Rächers, Weihe, Hammer der Rechtschaffenen, Richturteil und Heiliger Zorn. Schild der Rechtschaffenen, Ewige Flamme und Wort der Herrlichkeit liegen nicht auf der globalen Abklingzeit, daher leuchten sie neben der Rotation auf: Schild der Rechtschaffenen, wann immer Sie es sich leisten können, Ewige Flamme auf Ihnen selbst, wenn sie ausläuft, mit 3 Heiliger Kraft und drei Stapeln Bastion der Herrlichkeit, Wort der Herrlichkeit unter halber Gesundheit ohne dieses Talent. Weitere Erinnerungen: Zorn der Gerechtigkeit, Siegel der Einsicht, wenn ein anderes Siegel (außer Rechtschaffenheit) oder keines aktiv ist, Segen, Zurechtweisung, Geheiligter Schild, Zornige Vergeltung und Heiliger Rächer, während Sie tanken, sowie Wächter der Uralten Könige, Unermüdlicher Verteidiger, Göttlicher Schutz und Handauflegung je nach Ihrer Gesundheit. Sie kann eingehenden Schaden nicht sehen, planen Sie große Defensivfähigkeiten also selbst."
L["rm.mop.paladin.protection.simulator.Name"] = "Heilige Kraft sammeln (Simulation)"
L["rm.mop.paladin.protection.simulator.Description"] = "Eine Alternative zur empfohlenen integrierten Schutzrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Folgt den Tanklisten des Simulators: Schild der Rechtschaffenen wartet auf volle Heilige Kraft, außer Sie fallen unter 40 % Gesundheit oder Göttliche Bestimmung macht es kostenlos; Ewige Flamme kurz vor dem Auslaufen mit mehr als zwei Stapeln Bastion der Herrlichkeit; Geheiligter Schild aufrechterhalten; Heiliger Rächer und Zornige Vergeltung bei Abklingzeit-Ende. Die Generatoren laufen Kreuzfahrerstoß, Richturteil, dann Schild des Rächers, Heiliger Zorn, das Talent der Stufe 90 und Hammer des Zorns, mit derselben Flächenreihenfolge ab drei Gegnern. Auf Bosse abgestimmte Defensivfähigkeiten liegen bei Ihnen."
L["rm.mop.paladin.retribution.Name"] = "Empfohlen"
L["rm.mop.paladin.retribution.Description"] = "Empfohlen für Vergeltung ab Stufe 10 in der Spezialisierung Vergeltung. Hält Inquisition aufrecht (bei 3 Heiliger Kraft gewirkt, in ihren letzten 3 Sekunden erneuert; ab Stufe 81), gibt Urteil des Templers bei voller Heiliger Kraft oder bei einem kostenlosen Proc aus, bevor sie mehr erzeugt, dann Hammer des Zorns, Kreuzfahrerstoß, Richturteil und Exorzismus und Urteil des Templers bei 3, wenn nichts anderes bereit ist. Während Zorniger Vergeltung gibt sie sofort aus und stellt Richturteil vor Kreuzfahrerstoß. Zwei oder mehr Gegner gegen Sie wechseln zu Göttlicher Sturm, mit Hammer der Rechtschaffenen, wenn vier nah sind. Zieht aus der Distanz mit Richturteil oder Exorzismus und schlägt Wort der Herrlichkeit vor, wenn Sie solo und in Gefahr sind. Erinnerungen: Siegel der Wahrheit, wenn ein anderes Siegel oder keines aktiv ist (Siegel der Rechtschaffenheit bleibt erhalten), Segen der Könige oder der Macht, Zurechtweisung, Zornige Vergeltung und Wächter der Uralten Könige bei aktiver Inquisition gegen Elitegegner, Heiliger Rächer während Zorniger Vergeltung, Richtspruch und Hammer des Lichts sowie Göttlicher Schutz und Handauflegung bei niedriger Gesundheit. Siegel der Rechtschaffenheit für Gruppen und die Wahl der Glyphen bleiben Ihnen überlassen."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Exorzismus zuerst (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "Eine Alternative zur empfohlenen integrierten Vergeltungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Exorzismus bei jedem Abklingzeit-Ende und jedem Zurücksetzen durch Kriegskunst kommt zuerst; Inquisition wird bei beliebiger Heiliger Kraft gewirkt, wenn sie fehlt, und bei 3 in ihren letzten 20 Sekunden erneuert; dann Kreuzfahrerstoß, Richturteil, Urteil des Templers und Hammer des Zorns (zuerst während Zorniger Vergeltung mit Geweihtem Zorn). Zwei oder mehr Gegner nutzen Kreuzfahrerstoß, Hammer des Lichts, Richturteil, Göttlicher Sturm und Hammer des Zorns. Zornige Vergeltung und Wächter der Uralten Könige werden nur gegen Elitegegner vorgeschlagen. Das Siegel der Rechtschaffenheit des Leitfadens bei jedem Cleave bleibt Ihnen überlassen."
L["rm.mop.paladin.unspecialized.Name"] = "Vor einer Spezialisierung"
L["rm.mop.paladin.unspecialized.Description"] = "Für Stufe 1 bis 9 und jeden Paladin, der noch keine Spezialisierung gewählt hat; die integrierte Rotation einer Spezialisierung übernimmt, sobald Sie eine wählen. Zieht aus der Distanz mit Richturteil, dann Kreuzfahrerstoß und Richturteil, mit Hammer der Gerechtigkeit, wenn Sie solo und unter halber Gesundheit sind, und Wort der Herrlichkeit unter 40 %. Erinnerungen: Siegel des Befehls (Siegel der Wahrheit ab Stufe 24), wenn Sie nicht darin sind, Segen der Könige, Zurechtweisung und Lichtblitz außerhalb des Kampfes, wenn Sie verletzt sind."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "Heilig in Midnight, als Referenz: Rotation Master wählt einen Zauber, kein Ziel, und das Spiel verbirgt im Kampf die Gesundheit aller, daher hält diese Rotation Ihre Heilige Kraft und Abklingzeiten auf jedem Ziel, das Sie anvisieren, in Gang und überlässt Ihnen die Entscheidung, wer Heilung braucht. Heilige Kraft bleibt im Kampf sichtbar, daher wird sie zuerst bei 5 ausgegeben und ab 3 nach Ihren anderen Heilungen. Bei einem freundlichen Ziel: Ewige Flamme oder Wort der Herrlichkeit bei 5 Heiliger Kraft, Lichtblitz bei Lichtinfusion, Heiliger Schock, Ewige Flamme oder Wort der Herrlichkeit ab 3, Heiliges Licht, Lichtblitz; Licht der Morgendämmerung bleibt Ihnen überlassen. Bei einem Gegner: Schild der Rechtschaffenen bei 5 Heiliger Kraft, Heiliger Schock, Schild der Rechtschaffenen ab 3, Richturteil, Kreuzfahrerstoß, Weihe. Erinnerungen im Kampf: Göttlicher Glockenschlag, Heiliges Prisma, Heiliges Bollwerk oder Heilige Waffe, Leuchtfeuer der Tugend auf einem freundlichen Ziel, Göttlicher Schutz; eine Aura zwischen den Kämpfen; Zurechtweisung. Handauflegung bleibt Ihnen überlassen. Zornige Vergeltung und Aurenmeisterschaft bleiben Ihnen überlassen."
L["rm.retail.paladin.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.paladin.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Paladins meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Paladin-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.paladin.protection.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.paladin.protection.Description"] = "Empfohlen für Schutz in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent, der Schild der Rechtschaffenen, Zornige Vergeltung und Schildwache bereits enthält, und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: eine Aura zwischen den Kämpfen, Zurechtweisung bei einem unterbrechbaren Zauber sowie Unermüdlicher Verteidiger und Wächter der Uralten Könige, wann immer sie im Kampf bereit sind. Die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz dieser Fähigkeiten und von Handauflegung Ihnen überlassen. Spotten und Positionierung bleiben Ihnen überlassen."
L["rm.retail.paladin.protection.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft braucht die Stärkungszauber Weihe, Vorhut und Strahlendes Licht, die Midnight im Kampf verbirgt. Weihe vor dem Pull; dann Göttlicher Glockenschlag, Hammer des Lichts, Weihe, wenn Sie nicht darin stehen, Schild des Rächers mit Vorhut, Schild der Rechtschaffenen ab 3 Heiliger Kraft, Hammer des Zorns, Richturteil, Gesegneter Hammer oder Hammer der Rechtschaffenen, Schild des Rächers, Wort der Herrlichkeit mit Strahlendem Licht, Weihe. Erinnerungen: Zornige Vergeltung oder Schildwache, Heiliges Bollwerk, Heilige Waffe außerhalb von Zorniger Vergeltung, Defensivfähigkeiten, Aura, Zurechtweisung."
L["rm.retail.paladin.protection.wowhead.Name"] = "Weihe als Füller, Referenz (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Tank-Reihenfolge von Wowhead. Richturteil bei Abklingzeit-Ende, Schild der Rechtschaffenen, Schild des Rächers, Göttlicher Glockenschlag bei 0 Heiliger Kraft, Gesegneter Hammer oder Hammer der Rechtschaffenen und Weihe nur als Füller. Die Gesundheit ist unter Retail verborgen, daher bleibt Wort der Herrlichkeit unter halber Gesundheit Ihnen überlassen. Dieselben Erinnerungen wie die Referenz nach Icy Veins."
L["rm.retail.paladin.retribution.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.paladin.retribution.Description"] = "Empfohlen für Vergeltung in Midnight. Im Kampf verbirgt das Spiel nun Stärkungs- und Schwächungszauber, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation) auf Ihren Aktionsleisten und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Sie erinnert Sie außerdem an das, was dieser Vorschlag nie abdeckt: eine Aura zwischen den Kämpfen, Zurechtweisung bei einem unterbrechbaren Zauber und Göttlicher Schutz, wann immer er im Kampf bereit ist. Die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Göttlichem Schutz und Handauflegung Ihnen überlassen. Schmuckstücke und Volksfähigkeiten bleiben Ihnen überlassen."
L["rm.retail.paladin.retribution.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest Stärkungszauber, Aufladungen und Gegnerzahlen, die Midnight im Kampf verbirgt, daher kann sie dort nicht zuverlässig laufen. Hammer des Lichts; ein kostenloser Finisher durch Göttliche Bestimmung; bei 5 Heiliger Kraft, während Aschewelle abklingt, der Finisher; Aschewelle; Göttlicher Glockenschlag; Klinge der Gerechtigkeit bei Kunst des Krieges; Hammer des Zorns, bevor seine Aufladungen das Maximum erreichen; ab 3 Heiliger Kraft Göttlicher Sturm gegen zwei oder mehr Gegner (oder mit Himmlischer Macht), sonst Letztes Urteil; Hammer des Zorns; Klinge der Gerechtigkeit; Richturteil; Templerstoß oder Kreuzfahrerstoß. Heilige Kraft bleibt im Kampf sichtbar, daher funktionieren die Schritte, die sie ausgeben, dort. Erinnerungen: Zornige Vergeltung, Todesurteil bei bereiter Aschewelle, Aura, Zurechtweisung, Defensivfähigkeiten."
L["rm.sod.paladin.holy.Name"] = "Heilig (SoD)"
L["rm.sod.paladin.holy.Description"] = "Heilung in einer Gruppe in der Saison der Entdeckungen, gewählt durch eine gravierte Flamme des Glaubens, Göttliches Licht oder Geheiligten Schild oder den Heilig-Baum ohne Kreuzfahrerstoß. Wirkt auf Ihr freundliches Ziel: Reinigung des Glaubens, Heiliger Schock in Bewegung oder unter 30 %, Göttliches Licht (Heiliges Licht, wenn das Mana unter der Hälfte liegt) unter 60 %, Lichtblitz unter 90 %. Mit einem Gegner in Nahkampfreichweite hält sie nur ein Siegel aufrecht. Erinnerungen: Flamme des Glaubens und Geheiligter Schild auf dem Ziel, dem sie fehlen, Aura der Konzentration oder der Hingabe, Segen der Weisheit, Göttliche Gunst und Handauflegung für ein Ziel mit sehr wenig Gesundheit. Die zugrunde liegenden Leitfäden stammen aus Phase 4; wen Sie heilen, bleibt Ihnen überlassen."
L["rm.sod.paladin.holy.wowhead.Name"] = "Heilig, Heiliges Licht zuerst (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "Die Heilreihenfolge von Wowhead für Phase 4 bei Ausrüstung mit viel kritischer Trefferchance, eine Alternative zur empfohlenen integrierten Heilig-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Göttliches Licht oder Heiliges Licht unter 75 %, dann Reinigung des Glaubens, Heiliger Schock bei kleinen Defiziten oder in Bewegung, Lichtblitz unter 95 %. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.sod.paladin.protection.Name"] = "Schutz (SoD)"
L["rm.sod.paladin.protection.Description"] = "Tanken in der Saison der Entdeckungen, gewählt durch Zorn der Gerechtigkeit, einen gravierten Hammer der Rechtschaffenen oder Schild der Rechtschaffenheit oder den Schutzbaum. Siegel des Märtyrertums, ein Pull mit Heiligem Schild, Schild des Rächers und Exorzismus, Heiliger Schild aufrechterhalten; gegen ein Ziel Hammer der Rechtschaffenen, Schild der Rechtschaffenheit, Exorzismus, Schild des Rächers, Richturteil, Göttlicher Sturm, Weihe; wenn drei oder mehr Gegner gegen Sie kämpfen, Hammer der Rechtschaffenen, Schild des Rächers, Weihe, Schild der Rechtschaffenheit, Exorzismus. Erinnerungen: Zorn der Gerechtigkeit, Heiliger Schild vor einem Pull, Aura der Hingabe, Refugium oder Könige, Zornige Vergeltung, Göttlicher Schutz unter 40 %, Handauflegung, Hand der Abrechnung in einer Gruppe, wenn Ihr Ziel jemand anderen angreift."
L["rm.sod.paladin.protection.simulator.Name"] = "Schutz (SoD, Simulation)"
L["rm.sod.paladin.protection.simulator.Description"] = "Die Tankliste von Simulation, eine Alternative zur empfohlenen integrierten Schutzrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil, wann immer ein Siegel aktiv ist, das Siegel kurz vor dem Auslaufen erneuert, Heiliger Schild, Schild des Rächers, Hammer der Rechtschaffenen, Exorzismus, Schild der Rechtschaffenheit zuletzt. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.sod.paladin.retribution.Name"] = "Vergeltung (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Nahkampf in der Saison der Entdeckungen von Stufe 1 bis 60 und dort der Standard für jeden Paladin. Hält Siegel des Märtyrertums aufrecht (Rechtschaffenheit, bis Sie es haben), eröffnet mit Exorzismus, wirkt Göttlicher Sturm bei drei Heiliger Kraft, dann je nach Waffengeschwindigkeit: mit einer Zweihandwaffe von 3,3 Sekunden oder langsamer Kreuzfahrerstoß, Exorzismus, Göttlicher Sturm und Richturteil; mit einer schnelleren Richturteil nur, wenn das Siegel ausläuft, dann Exorzismus, Kreuzfahrerstoß und Göttlicher Sturm. Weihe bei genug Mana oder gegen drei nahe Gegner, Heiliger Zorn gegen Untote und Dämonen (gegen alles mit eingravierter Rune „Purifying Power“), Hammer des Zorns bei überschüssigem Mana (immer mit eingravierter Rune „Improved Hammer of Wrath“). Runen werden genutzt, sobald Sie sie gravieren. Erinnerungen: Aura der Heiligkeit, ein Segen, Zornige Vergeltung mit Aurenmeisterschaft, eine Heilung zwischen den Kämpfen, Gottesschild kurz vor dem Tod."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Vergeltung (SoD, Icy Veins Phase 4)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "Die ältere Liste für Phase 4 von Icy Veins und Warcraft Tavern, auch gut zum Leveln, eine Alternative zur empfohlenen integrierten Vergeltungsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Einmal Richturteil des Kreuzfahrers gegen Elitegegner und bei langen Kämpfen, Siegel des Märtyrertums, Exorzismus, Kreuzfahrerstoß, Göttlicher Sturm und Richturteil bei Abklingzeit-Ende, Weihe bei genug Mana oder gegen drei nahe Gegner, Hammer des Zorns. Dieselben Erinnerungen wie die empfohlene Rotation."
L["rm.sod.paladin.retribution.stacking.Name"] = "Vergeltung, Siegel-Stacking (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie mit der Rune Seele des Siegelträgers oder dem Sechsteile-Set, durch das Siegel nachwirken (Rotation Master kann keines von beiden erkennen). Hält Siegel des Befehls und Siegel des Märtyrertums beide aufrecht, Göttlicher Sturm bei drei Heiliger Kraft, Kreuzfahrerstoß, Exorzismus, Heiliger Zorn gegen Untote und Dämonen (gegen alles mit eingravierter Rune „Purifying Power“), Weihe und Richturteil, solange beide Siegel aktiv sind."
L["rm.sod.paladin.retribution.twist.Name"] = "Vergeltung, Siegel-Twisting (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie mit einer langsamen Zweihandwaffe twisten. Wechselt in den letzten 0,4 Sekunden vor jedem Schlag zwischen Siegel des Märtyrertums und Siegel des Befehls, schlägt in den 1,9 Sekunden davor nichts auf der globalen Abklingzeit vor, richtet, solange beide Siegel nachwirken, und nutzt einen Füller pro Schlag: Göttlicher Sturm bei drei Heiliger Kraft, Kreuzfahrerstoß, Exorzismus. Benötigt einen Schlagtimer und Übung."
L["rm.sod.paladin.shockadin.Name"] = "Shockadin (SoD, Simulation)"
L["rm.sod.paladin.shockadin.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie mit dem Heilig-Baum Schaden verursachen. Sie gilt, wenn Heilig Ihr Haupttalentbaum ist und die Rune „Shock and Awe“ eingraviert ist. Siegel des Märtyrertums (sonst Rechtschaffenheit), gerichtet, wenn es ausläuft, Heiliger Schock, um Sonnenlicht aufrechtzuerhalten, oder bei drei Heiliger Kraft, Exorzismus und Kreuzfahrerstoß. Dieselben Erinnerungen wie die integrierte Vergeltungsrotation der Saison der Entdeckungen."
L["rm.tbc.paladin.holy.Name"] = "Heilig (Icy Veins & Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Heilung für einen Heilig-Paladin in einer Gruppe, auf Ihr freundliches Ziel: Handauflegung oder Heiliger Schock für ein sterbendes Ziel, Reinigung des Glaubens (Läutern vor Stufe 42), Heiliger Schock in Bewegung, Heiliges Licht bei hohem Schaden, Heiliges Licht Rang 5, um Anmut des Lichts aufrechtzuerhalten, sonst Lichtblitz. Mit einem feindlichen Ziel hält sie Richturteil der Weisheit aufrecht. Erinnerungen: Aura der Konzentration, Segen der Weisheit, Göttliche Eingebung und Göttliche Gunst. Ein Heilig-Paladin im Solospiel erhält stattdessen eine integrierte Vergeltungsrotation."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Heilig (Wowhead, Tankheilung)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Schlachtzugs-Tankheilung nach Wowhead, eine Alternative zur empfohlenen integrierten Heilig-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Heiliges Licht, sobald Ihrem Ziel ein Zehntel seiner Gesundheit fehlt, Lichtblitz nur bei kleinen Defiziten, mit denselben Notfällen, Reinigungen, Richturteilen und Erinnerungen wie die kombinierte integrierte Heilig-Rotation."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Schutz (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "Tanken nach Icy Veins, eine Alternative zur empfohlenen integrierten Schutzrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers, wenn niemand es aufrechterhält, Rechtschaffenheit (Weisheit gegen Gruppen), Weihe als Hauptquelle der Bedrohung, Richturteil, Heiliger Schild, dann Schild des Rächers und Hammer des Zorns bei Abklingzeit-Ende. Dieselben Erinnerungen wie die Wowhead-Variante, ohne Zornige Vergeltung."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Schutz (Wowhead & Simulation)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Tanken für den Schutzbaum oder jeden Paladin mit aktivem Zorn der Gerechtigkeit. Zieht mit Heiligem Schild, Schild des Rächers und Richturteil; gegen ein Ziel mit zerschmetternden Schlägen (Weltboss oder drei oder mehr Stufen über Ihnen) kommt Heiliger Schild zuerst; dann Weihe, Exorzismus gegen Untote und Dämonen, Richturteil, Heiliger Schild, Heiliger Zorn gegen Gruppen von Untoten, Schild des Rächers außer gegen Ziele mit zerschmetternden Schlägen. Siegel der Weisheit gegen Gruppen bei knappem Mana, sonst Rechtschaffenheit. Erinnerungen: Zorn der Gerechtigkeit, Aura der Hingabe, Refugium (oder Könige oder Weisheit), Zornige Vergeltung, Handauflegung. Spotten und Zielwechsel bleiben Ihnen überlassen."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Vergeltung (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "Vergeltung nach Icy Veins, eine Alternative zur empfohlenen integrierten Vergeltungsrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers einmal pro Ziel, Siegel der Rechtschaffenheit (Befehl nur mit einer langsamen Waffe, Blut oder Märtyrer, sobald erlernt), Kreuzfahrerstoß, Hammer des Zorns und Richturteil bei Abklingzeit-Ende, Weihe gegen zwei oder mehr Gegner, Exorzismus gegen Untote und Dämonen und Heiliger Schock für Heilig-Leveler. Dieselben Erinnerungen wie die Wowhead-Variante."
L["rm.tbc.paladin.retribution.twist.Name"] = "Vergeltung mit Siegel-Twisting"
L["rm.tbc.paladin.retribution.twist.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie Siegel twisten (ab Stufe 64, Siegel des Befehls und Blut oder Märtyrer). Eröffnet mit Richturteil des Kreuzfahrers, dann setzt jeder Schlag früh Siegel des Befehls (Rang 1) und wechselt in den letzten 0,4 Sekunden zu Blut oder Märtyrer, Kreuzfahrerstoß zwischen den Wechseln, richtet nur Blut oder Märtyrer, Exorzismus und Weihe nur als Füller und hält unter 12 % Mana Blut ohne Twisting aufrecht. Benötigt einen zuverlässigen Schlagtimer; die Latenz wird nicht berücksichtigt."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Vergeltung (Wowhead & Simulation)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Vergeltung im Nahkampf von Stufe 1 bis 70 und der Standard für jeden Paladin, zu dem keine andere integrierte Rotation passt. Eröffnet jedes Ziel mit Richturteil der Weisheit (wenig Mana) oder des Kreuzfahrers, hält Ihr bestes Siegel aufrecht (Blut oder Märtyrer, Befehl, dann Rechtschaffenheit), Kreuzfahrerstoß, richtet nur Rechtschaffenheit, Blut oder Märtyrer (oder Befehl auf ein betäubtes Ziel), Exorzismus gegen Untote und Dämonen, Weihe für drei oder mehr Gegner bei überschüssigem Mana. Hammer des Zorns bleibt Ihnen überlassen (Wowhead nutzt ihn nur gegen fliehende Ziele). Erinnerungen: Aura der Heiligkeit, der Vergeltung oder der Hingabe, ein Segen auf Sie selbst, eine Heilung nach dem Kampf, Zornige Vergeltung. Siegel-Twisting ist eine eigene integrierte Rotation."
